//! Shared hermetic fixture for Tauri command unit tests.
//!
//! Seed inventory (verified by the tests in this module):
//! - profile/identity: generated by `DesktopRuntime` from a temporary profile
//!   directory — no persisted profile row is required or read.
//! - group conversations: two persisted group entries, `Fixture Alpha` (last
//!   activity 1_700_000_002_000) and `Fixture Beta` (1_700_000_001_000), so
//!   `get_bootstrap().rooms` / `list_conversations` return non-empty,
//!   deterministically ordered rows.
//! - contacts: two `contacts` rows with `last_seen_ms` 2_000 and 1_000, so
//!   `get_contacts` returns two DTOs ordered by `last_seen_ms DESC`. Display
//!   names are projected from the contact key by the handler, never persisted.
//! - settings: exactly one `kv_store` row, `theme = "dark"`.
//! - network status: derived from the loopback-only endpoint (relay, mDNS and
//!   DHT disabled), so `get_network_status` is a real runtime projection rather
//!   than seeded data.
//!
//! Everything is hermetic: `tempfile::TempDir` profile, no network, no reads of
//! the developer home directory or real app data paths.

use super::{AppState, DesktopRuntime, DesktopRuntimeConfig};
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use tempfile::TempDir;

use boru_core::conversations::ConversationEntry;
use boru_core::conversations::ConversationStore;
use boru_core::proto::TopicId;

/// Seeded group conversation name plus its activity ordering key.
pub(crate) const SEED_ROOM_ALPHA: (&str, u64) = ("Fixture Alpha", 1_700_000_002_000);
/// Seeded group conversation name plus its activity ordering key.
pub(crate) const SEED_ROOM_BETA: (&str, u64) = ("Fixture Beta", 1_700_000_001_000);
/// Seeded contact ordering keys (`last_seen_ms`), descending in `list_contacts`.
pub(crate) const SEED_CONTACT_LAST_SEEN: [u64; 2] = [2_000, 1_000];
/// The single seeded setting.
pub(crate) const SEED_THEME: &str = "dark";

/// Owns the temporary profile directory for as long as its runtime is alive.
pub(crate) struct TestApp {
    pub(crate) _dir: TempDir,
    pub(crate) state: AppState,
}

impl TestApp {
    /// Borrow the started runtime, panicking if the fixture is misused.
    pub(crate) fn runtime(&self) -> std::sync::MutexGuard<'_, Option<DesktopRuntime>> {
        self.state.runtime.lock().expect("runtime lock")
    }
}

/// Start a seeded, network-isolated application state for command tests.
pub(crate) async fn test_app_state() -> TestApp {
    let dir = tempfile::tempdir().expect("temporary test profile");
    let config = DesktopRuntimeConfig {
        data_dir: dir.path().to_path_buf(),
        secret_key: None,
        relay_mode: iroh::RelayMode::Disabled,
        bind_port: 0,
        enable_mdns: false,
        enable_dht: false,
        publish_direct_addresses: false,
    };
    let (runtime, _handles) = DesktopRuntime::start_from_config(config)
        .await
        .expect("isolated test runtime starts");

    seed_settings(&runtime);
    seed_conversations(&runtime, dir.path());
    seed_contacts(&runtime);

    TestApp {
        _dir: dir,
        state: AppState {
            runtime: Arc::new(Mutex::new(Some(runtime))),
            page_requests: Arc::new(Mutex::new(HashMap::new())),
        },
    }
}

/// Seed the single `kv_store` setting row consumed by `get_settings`.
fn seed_settings(runtime: &DesktopRuntime) {
    runtime
        .storage()
        .kv_set("theme", SEED_THEME)
        .expect("seed test setting");
}

/// Seed the persisted conversation catalog consumed by the `rooms` projection.
fn seed_conversations(runtime: &DesktopRuntime, data_dir: &std::path::Path) {
    let mut store = ConversationStore::empty_at(data_dir);
    for (seed, (name, last_seen)) in [(0xA1u8, SEED_ROOM_ALPHA), (0xB2u8, SEED_ROOM_BETA)] {
        let mut entry = ConversationEntry::new_group(TopicId::from_bytes([seed; 32]), name);
        entry.created_at_unix_ms = 1_700_000_000_000;
        entry.last_seen_at_unix_ms = last_seen;
        store.upsert(entry);
    }
    store
        .save_to_sqlite(runtime.storage())
        .expect("persist seeded conversations");
}

/// Seed the contact rows consumed by `get_contacts`.
fn seed_contacts(runtime: &DesktopRuntime) {
    for (idx, last_seen_ms) in SEED_CONTACT_LAST_SEEN.iter().enumerate() {
        let user = iroh::SecretKey::generate().public();
        let device = iroh::SecretKey::generate().public();
        let identity_key = [0x10u8 + idx as u8; 32];
        runtime
            .storage()
            .upsert_contact(
                &user,
                &device,
                None,
                &identity_key,
                *last_seen_ms,
                9_999_999,
            )
            .expect("seed contact row");
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use boru_core::conversations::ConversationKind;

    #[tokio::test]
    async fn fixture_is_callable_and_uses_temporary_profile() {
        let fixture = test_app_state().await;
        let guard = fixture.runtime();
        let runtime = guard.as_ref().expect("runtime is available");
        assert_eq!(
            runtime
                .storage()
                .kv_get_read_only("theme")
                .unwrap()
                .as_deref(),
            Some(SEED_THEME)
        );
    }

    #[tokio::test]
    async fn fixture_seeds_ordered_group_rooms() {
        let fixture = test_app_state().await;
        let guard = fixture.runtime();
        let runtime = guard.as_ref().expect("runtime is available");
        let store = runtime.conversations();
        let mut rooms: Vec<(String, u64)> = store
            .iter()
            .filter(|entry| entry.kind == ConversationKind::Group && !entry.archived)
            .map(|entry| (entry.name.clone(), entry.last_seen_at_unix_ms))
            .collect();
        rooms.sort_by(|a, b| b.1.cmp(&a.1));
        assert_eq!(
            rooms,
            vec![
                (SEED_ROOM_ALPHA.0.to_string(), SEED_ROOM_ALPHA.1),
                (SEED_ROOM_BETA.0.to_string(), SEED_ROOM_BETA.1),
            ]
        );
    }

    #[tokio::test]
    async fn fixture_seeds_ordered_contacts() {
        let fixture = test_app_state().await;
        let guard = fixture.runtime();
        let runtime = guard.as_ref().expect("runtime is available");
        let contacts = runtime.storage().list_contacts().expect("list contacts");
        let last_seen: Vec<u64> = contacts.iter().map(|c| c.last_seen_ms).collect();
        assert_eq!(last_seen, SEED_CONTACT_LAST_SEEN.to_vec());
    }

    // These call the exact projection functions that the `#[tauri::command]`
    // wrappers delegate to (`crate::*_inner`). Only the thin `tauri::State`
    // wrapper is out of reach here, because `State`'s constructor is private;
    // the assertions therefore run against the real handler projection code.
    #[tokio::test]
    async fn get_bootstrap_returns_seeded_rooms_and_runtime_identity() {
        let fixture = test_app_state().await;
        let guard = fixture.runtime();
        let runtime = guard.as_ref().expect("runtime is available");
        let snapshot = crate::bootstrap_inner(runtime).expect("bootstrap projection");

        assert_eq!(
            snapshot.schema_version,
            boru_core::snapshot::SNAPSHOT_SCHEMA_VERSION
        );
        let identity = snapshot.identity.as_ref().expect("runtime identity");
        assert_eq!(
            identity.id.len(),
            64,
            "public identity is a 32-byte hex key"
        );
        assert!(identity.id.chars().all(|ch| ch.is_ascii_hexdigit()));
        let rooms: Vec<_> = snapshot
            .rooms
            .iter()
            .map(|r| (r.name.as_str(), r.last_activity_at_ms))
            .collect();
        assert_eq!(
            rooms,
            vec![
                (SEED_ROOM_ALPHA.0, Some(SEED_ROOM_ALPHA.1)),
                (SEED_ROOM_BETA.0, Some(SEED_ROOM_BETA.1))
            ]
        );
    }

    #[tokio::test]
    async fn list_conversations_returns_exact_seeded_room_set() {
        let fixture = test_app_state().await;
        let guard = fixture.runtime();
        let runtime = guard.as_ref().expect("runtime is available");
        let rooms = crate::conversations_inner(runtime).expect("conversation projection");
        assert_eq!(rooms.len(), 2);
        assert_eq!(
            rooms
                .iter()
                .map(|room| room.name.as_str())
                .collect::<Vec<_>>(),
            vec![SEED_ROOM_ALPHA.0, SEED_ROOM_BETA.0]
        );
        assert_eq!(rooms[0].last_activity_at_ms, Some(SEED_ROOM_ALPHA.1));
        assert_eq!(rooms[1].last_activity_at_ms, Some(SEED_ROOM_BETA.1));
    }

    #[tokio::test]
    async fn get_contacts_returns_one_projected_dto_per_seeded_contact() {
        let fixture = test_app_state().await;
        let guard = fixture.runtime();
        let runtime = guard.as_ref().expect("runtime is available");
        let contacts = crate::contacts_inner(runtime).expect("contacts projection");
        assert_eq!(contacts.len(), SEED_CONTACT_LAST_SEEN.len());
        assert!(
            contacts
                .iter()
                .all(|c| c.id.len() == 64 && c.display_name == c.id),
            "ids/display names are hex renderings of the 32-byte contact keys"
        );
        assert!(contacts
            .iter()
            .all(|c| c.id.chars().all(|ch| ch.is_ascii_hexdigit())));
        assert!(contacts
            .iter()
            .all(|c| matches!(c.status, boru_core::snapshot::ContactStatusDto::Accepted)));
        assert_ne!(contacts[0].id, contacts[1].id, "seeded keys differ");
    }

    #[tokio::test]
    async fn get_network_status_returns_live_loopback_health() {
        let fixture = test_app_state().await;
        let guard = fixture.runtime();
        let runtime = guard.as_ref().expect("runtime is available");
        // Runtime-derived, not seeded: the loopback endpoint reports its own
        // health, so this asserts the real projection rather than fixture data.
        let health = crate::network_status_inner(runtime).expect("network projection");
        assert!(health.ready);
        assert!(!health.status.is_empty());
        assert_eq!(health.relay_url, None);
    }

    #[tokio::test]
    async fn get_settings_returns_seeded_theme() {
        let fixture = test_app_state().await;
        let guard = fixture.runtime();
        let runtime = guard.as_ref().expect("runtime is available");
        let settings = crate::settings_inner(runtime).expect("settings projection");
        assert_eq!(settings.theme.as_deref(), Some(SEED_THEME));
        assert_eq!(
            settings.schema_version,
            boru_core::snapshot::SNAPSHOT_SCHEMA_VERSION
        );
    }

    #[test]
    fn paging_validation_errors_have_exact_structured_codes() {
        use serde_json::Value;
        let cases = [
            (
                crate::bridge::PageParams::new(Some(0)).unwrap_err(),
                "INVALID_PARAM",
            ),
            (
                crate::bridge::PageParams::new(Some(201)).unwrap_err(),
                "INVALID_PARAM",
            ),
            (
                crate::bridge::decode_cursor("garbage").unwrap_err(),
                "INVALID_PARAM",
            ),
            (
                crate::bridge::AppError::NotFound {
                    entity: "conversation".into(),
                    id: "missing".into(),
                },
                "NOT_FOUND",
            ),
        ];
        for (error, expected_code) in cases {
            let envelope: Value = serde_json::from_str(&error.to_json()).unwrap();
            assert_eq!(envelope["code"], expected_code);
        }
    }

    #[test]
    fn read_command_database_work_is_offloaded_from_ui_executor() {
        let source = include_str!("lib.rs");
        assert!(source.contains("tauri::async_runtime::spawn_blocking"));
        assert!(source.contains("run_cancellable_blocking"));
    }
}
